/// A primary administrative subdivision of a DXCC entity, such as a province,
/// state, or oblast.
///
/// The specification defines these per DXCC entity in its section III.B.12, and
/// a code is only meaningful inside the entity that defines it. Look one up with
/// `init(code:dxccEntityCode:)` rather than treating the code as global.
///
/// - Note: Some entities group their codes under a district heading, such as
///   Austria's states under `Wien`, which is reported by `region`.
public struct ADIPrimaryAdministrativeSubdivision: Hashable, Sendable, CustomStringConvertible {
    /// The subdivision code, as the specification spells it.
    public let code: String

    /// The subdivision's name.
    public let name: String

    /// The DXCC entity that defines this subdivision.
    public let dxccEntityCode: String

    /// The DXCC entity's name.
    public let dxccEntityName: String

    /// The district or region this subdivision sits within, where the entity
    ///   groups its codes that way.
    ///
    /// - Note: `nil` where the specification lists the subdivision without a
    ///   grouping heading.
    public let region: String?

    /// The oblast number, where the specification gives one.
    public let oblast: String?

    /// The CQ zone or zones this subdivision lies in.
    public let cqZone: String?

    /// The ITU zone or zones this subdivision lies in.
    public let ituZone: String?

    /// Whether the specification has retired this subdivision.
    ///
    /// - Note: A retired subdivision is kept rather than dropped so a log that
    ///   used it still validates.
    public let isDeleted: Bool

