    private static let subdivisionsByKey: [String: [ADIPrimaryAdministrativeSubdivision]] = {
        var index = [String: [ADIPrimaryAdministrativeSubdivision]](minimumCapacity: Self.allSubdivisions.count)
        for subdivision in Self.allSubdivisions {
            index[Self.key(code: subdivision.code, dxccEntityCode: subdivision.dxccEntityCode), default: []].append(subdivision)
        }

        return index
    }()

    private static let subdivisionsByDXCCEntity: [String: [ADIPrimaryAdministrativeSubdivision]] = {
        var index = [String: [ADIPrimaryAdministrativeSubdivision]](minimumCapacity: 66)
        for subdivision in Self.allSubdivisions {
            index[subdivision.dxccEntityCode, default: []].append(subdivision)
        }

        return index
    }()

    /// The subdivision's code.
    public var description: String {
        code
    }

    /// Creates a subdivision from its specification data.
    ///
    /// - Parameters:
    ///   - code: The subdivision's code.
    ///   - name: The subdivision's name.
    ///   - dxccEntityCode: The subdivision's dxccEntityCode.
    ///   - dxccEntityName: The subdivision's dxccEntityName.
    ///   - region: The subdivision's region.
    ///   - oblast: The subdivision's oblast.
    ///   - cqZone: The subdivision's cqZone.
    ///   - ituZone: The subdivision's ituZone.
    ///   - isDeleted: Whether the specification has retired the subdivision.
    public init(
        code: String,
        name: String,
        dxccEntityCode: String,
        dxccEntityName: String,
        region: String? = nil,
        oblast: String? = nil,
        cqZone: String? = nil,
        ituZone: String? = nil,
        isDeleted: Bool = false
    ) {
        self.code = code
        self.name = name
        self.dxccEntityCode = dxccEntityCode
        self.dxccEntityName = dxccEntityName
        self.region = region
        self.oblast = oblast
        self.cqZone = cqZone
        self.ituZone = ituZone
        self.isDeleted = isDeleted
    }

    /// Creates a subdivision by looking up its code within a DXCC entity.
    ///
    /// - Parameters:
    ///   - code: The subdivision code, in any case.
    ///   - dxccEntityCode: The DXCC entity code that defines it.
    /// - Returns: The matching subdivision, or `nil` if the specification
    ///   defines no subdivision with that code in that entity.
    /// - Note: The DXCC entity is required because a code is reused across
    ///   entities and means something different in each. Where a code is reused
    ///   within one entity, this returns the first candidate in specification
    ///   order; see `subdivisions(code:dxccEntityCode:)` for all of them.
    public init?(code: some StringProtocol, dxccEntityCode: some StringProtocol) {
        guard let candidates = Self.subdivisionsByKey[
            Self.key(code: code, dxccEntityCode: dxccEntityCode)
        ], let subdivision = candidates.first else {
            return nil
        }

        self = subdivision
    }

    /// Returns every subdivision the specification defines with a code in a
    /// DXCC entity.
    ///
    /// - Parameters:
    ///   - code: The subdivision code, in any case.
    ///   - dxccEntityCode: The DXCC entity code that defines it.
    /// - Returns: The matching subdivisions in specification order, which is empty
    ///   where the specification defines none.
    /// - Note: The specification reuses a code across a boundary change, naming
    ///   both the subdivision retired at a date and the one that replaced it --
    ///   `PM` in Asiatic Russia, for instance. Use this where that matters, and
    ///   `init(code:dxccEntityCode:)` where the first candidate will do.
    public static func subdivisions(code: some StringProtocol,
                                dxccEntityCode: some StringProtocol) -> [ADIPrimaryAdministrativeSubdivision] {
        Self.subdivisionsByKey[Self.key(code: code, dxccEntityCode: dxccEntityCode)] ?? []
    }

    /// Returns every primary subdivision the specification defines in a DXCC
    /// entity.
    ///
    /// - Parameter dxccEntityCode: The DXCC entity code.
    /// - Returns: That entity's subdivisions, in specification order.
    public static func subdivisions(inDXCCEntity dxccEntityCode: some StringProtocol) -> [ADIPrimaryAdministrativeSubdivision] {
        Self.subdivisionsByDXCCEntity[String(dxccEntityCode)] ?? []
    }

    private static func key(code: some StringProtocol,
                           dxccEntityCode: some StringProtocol) -> String {
        "\(dxccEntityCode.uppercased())/\(code.uppercased())"
    }
}
